import {createSubmissionKeys} from './submission-keys.js';

export const taskNotesMarkup=`<section id="community-notes" aria-label="任务留言">
  <div class="chat-topline"><div><h3>关联任务的使用计划</h3><p>关联留言随任务结束清理；长期内容请发帖，也可选择手动保留。</p></div><button class="button" id="notes-refresh" type="button">刷新</button></div>
  <div id="task-notes-list" class="community-posts"></div><button class="button community-more" id="notes-more" type="button" hidden>加载更多</button>
  <form id="task-note-form"><label for="task-note-lifetime">留言保留方式</label><select id="task-note-lifetime" required><option value="">请选择</option><option value="task">随任务结束删除</option><option value="general">非任务留言，手动删除</option></select>
  <label id="task-note-job-field" hidden>我的未结束任务<select id="task-note-job"></select></label>
  <label for="task-note-body">留言内容</label><textarea id="task-note-body" rows="3" maxlength="2000" required></textarea>
  <div class="chat-compose-footer"><p>所有登录成员可见。任务状态未知或停止尚未确认时，留言继续保留。</p><button class="button primary" type="submit">发布留言</button></div><p id="task-note-error" class="form-error" role="status"></p></form>
  <dialog id="task-note-editor" class="community-dialog"><form><div class="modal-head"><h2>编辑留言</h2><button type="button" class="icon-button" data-note-close aria-label="关闭">×</button></div><label>留言内容<textarea name="body" maxlength="2000" rows="4" required></textarea></label><p data-note-edit-error class="form-error" role="status"></p><div class="modal-actions"><button class="button primary" type="submit">保存修改</button></div></form></dialog>
</section>`;
const ended=new Set(['SUCCEEDED','FAILED','CANCELED']);
export function selectableNoteJobs(store){return store.jobs.filter(job=>!ended.has(job.state));}
function element(tag,text,className){const node=document.createElement(tag);if(text!==undefined)node.textContent=text;if(className)node.className=className;return node;}
export function createTaskNotesUI(root,store,toast,options={}){
  // The optional prefix lets the task drawer reuse the same permission and
  // idempotency handling while the collaboration room stays mounted.
  const q=selector=>root.querySelector(options.prefix?selector.replace(/#([a-z][a-z-]*)/g,(_,id)=>'#'+options.prefix+id):selector),keys=createSubmissionKeys(),identity=store.principal?.userId;
  let epoch=0,active=false,enabled=false,busy=false,loading=false,rows=[],cursor=null,request=0,timer=null,editing=null;
  const valid=stamp=>stamp===epoch&&store.principal?.userId===identity;
  const error=(text='')=>{q('#task-note-error').textContent=text;};
  function stop(){clearTimeout(timer);timer=null;}
  function arm(){stop();if(active&&enabled&&!document.hidden)timer=setTimeout(()=>load(),5000);}
  // A task can finish during a send or lost reply; keep its original option
  // until that exact idempotent request is acknowledged by the backend.
  function jobOptions(){if(busy||keys.hasUncertain('note'))return;const select=q('#task-note-job'),selected=select.value;jobs(selectableNoteJobs(store).filter(job=>!options.jobId||job.id===options.jobId));select.value=selected||options.jobId||'';
    function jobs(items){select.replaceChildren(element('option',items.length?'选择任务':'没有未结束任务'));select.firstChild.value='';for(const job of items){const option=element('option',`${job.name||'训练'} · ${job.machine} · ${job.state} · ${job.id}`);option.value=job.id;select.append(option);}}
  }
  function controls(){const uncertain=keys.hasUncertain('note');q('#task-note-lifetime').disabled=!enabled||busy||uncertain;q('#task-note-job').disabled=!enabled||busy||uncertain;q('#task-note-body').readOnly=busy||uncertain;q('#task-note-form [type=submit]').disabled=!enabled||busy;q('#notes-refresh').disabled=!enabled;q('#notes-more').disabled=!enabled||loading;q('#task-note-job-field').hidden=q('#task-note-lifetime').value!=='task';q('#task-note-job').required=q('#task-note-lifetime').value==='task';}
  function render(){const list=q('#task-notes-list');list.replaceChildren();const visible=options.jobId?rows.filter(note=>note.jobId===options.jobId):rows;for(const note of visible){const row=element('article',undefined,'task-note community-comment');row.dataset.noteId=note.id;const job=store.jobs.find(item=>item.id===note.jobId),scope=note.jobId?`任务 ${job?.name||note.jobId}${job?.machine?' · '+job.machine:''} · 结束后删除`:'非任务留言 · 手动删除';row.append(element('p',scope,'community-tag'),element('p',`${note.author.name||note.author.username} · ${new Date(note.createdAt).toLocaleString('zh-CN')}`,'community-meta'),element('p',note.body,'community-body'));const actions=element('div',undefined,'community-item-actions');if(note.canEdit)actions.append(action('编辑',()=>edit(note)));if(note.canDelete)actions.append(action('删除',()=>remove(note)));row.append(actions);list.append(row);}if(!visible.length)list.append(element('p',options.jobId?'这页暂无关联留言；可继续加载较早记录。':'暂无留言。','community-empty'));q('#notes-more').hidden=!cursor;}
  function action(text,callback){const button=element('button',text,'community-text-button');button.type='button';button.addEventListener('click',callback);return button;}
  async function load(more=false){if(!enabled||loading)return;loading=true;const stamp=epoch,seq=++request;controls();try{const result=await store.call('community.notes.list',{limit:50,...(more&&cursor?{before:cursor}:{})});if(!valid(stamp)||seq!==request)return;rows=more?[...rows,...result.notes.filter(item=>!rows.some(row=>row.id===item.id))]:result.notes;cursor=result.nextCursor;render();jobOptions();}catch(e){if(valid(stamp))error('读取留言失败：'+e.message);}finally{if(valid(stamp)){loading=false;controls();arm();}}}
  q('#task-note-lifetime').addEventListener('change',()=>{jobOptions();controls();});q('#notes-refresh').addEventListener('click',()=>load());q('#notes-more').addEventListener('click',()=>load(true));
  q('#task-note-form').addEventListener('submit',async event=>{event.preventDefault();if(busy||!enabled)return;const lifetime=q('#task-note-lifetime').value,jobId=q('#task-note-job').value;if(!['task','general'].includes(lifetime)||lifetime==='task'&&!jobId){error('请明确选择保留方式，任务留言还需选择任务。');return;}
    const payload={body:q('#task-note-body').value,...(lifetime==='task'?{jobId}:{})},stamp=epoch;busy=true;controls();error();try{const result=await store.call('community.notes.create',keys.request('note',payload));if(!valid(stamp))return;keys.confirmed('note');q('#task-note-body').value='';error(result.deleted?'任务留言已随任务结束删除，没有重复发布。':'');await load();}catch(e){if(valid(stamp)){if(!e.status||e.status>=500&&e.status!==507)keys.uncertain('note');else if(!keys.hasUncertain('note'))keys.confirmed('note');error(keys.hasUncertain('note')?'发送结果未确认。重试原内容会使用同一提交键。':e.message);}}finally{if(valid(stamp)){busy=false;controls();}}});
  function edit(note){editing=note;q('#task-note-editor [name=body]').value=note.body;q('[data-note-edit-error]').textContent='';q('#task-note-editor').showModal();}
  q('[data-note-close]').addEventListener('click',()=>q('#task-note-editor').close());q('#task-note-editor').addEventListener('close',()=>{editing=null;q('#task-note-editor [name=body]').value='';});
  q('#task-note-editor form').addEventListener('submit',async event=>{event.preventDefault();if(!editing)return;const current=editing,stamp=epoch,submit=event.currentTarget.querySelector('[type=submit]');submit.disabled=true;try{await store.call('community.notes.update',{id:current.id,body:q('#task-note-editor [name=body]').value});if(!valid(stamp)||editing!==current)return;q('#task-note-editor').close();await load();toast('留言已更新。');}catch(e){if(valid(stamp)&&editing===current)q('[data-note-edit-error]').textContent=e.status===409?'留言已被修改。你的草稿保留，请关闭并刷新后重新编辑。':e.message;}finally{if(valid(stamp))submit.disabled=false;}});
  async function remove(note){if(!window.confirm('删除这条留言？'))return;const stamp=epoch;try{await store.call('community.notes.delete',{id:note.id});if(!valid(stamp))return;await load();toast('留言已删除。');}catch(e){if(valid(stamp))error(e.status===409?'留言已被修改，请刷新后重新确认删除。':e.message);}}
  const visibility=()=>{if(document.hidden)stop();else if(active)load();};document.addEventListener('visibilitychange',visibility);
  return {sync(visible,capable){const entered=visible&&(!active||capable&&!enabled);active=visible;enabled=capable;controls();if(active){jobOptions();if(enabled&&entered){error();load();}else if(!enabled)error('节点尚未提供任务留言功能，请更新后台后使用。');}else stop();},reset(){epoch++;active=false;enabled=false;stop();keys.reset();document.removeEventListener('visibilitychange',visibility);q('#task-note-editor')?.close();}};
}
